// Vendored from herdr-mobile rust/crates/acp/src/update.rs (see UPSTREAM). Regenerated by scripts/sync-vendored.sh; do not edit.
use serde_json::Value;

/// What a non-text content block is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PartKind {
    /// A picture (`image`).
    Image,
    /// Sound (`audio`).
    Audio,
    /// A file the sender points at (`resource_link`).
    Link,
    /// A file the sender includes (`resource`, embedded context).
    Resource,
}

/// A non-text content block of a message or a tool's output: what a screen can name and, for a small
/// picture, show. The bytes of anything big are left out and counted in `size`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Part {
    /// What it is.
    pub kind: PartKind,
    /// What the person reads: the file's name, or `image` / `audio` when it has none.
    pub name: String,
    /// Where it lives (`file:///...`), when the block says.
    pub uri: Option<String>,
    /// `image/png`... when the block says.
    pub mime: Option<String>,
    /// Bytes in the file or the decoded sound or picture, when known.
    pub size: Option<u64>,
    /// The picture, base64, when it is small enough to carry ([`PART_DATA_MAX`]).
    pub data: Option<String>,
}

/// The most base64 characters of a picture a [`Part`] keeps; a bigger one is only named.
pub const PART_DATA_MAX: usize = 512 * 1024;

/// The part of a message chunk a client can show.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Content {
    Text(String),
    /// An `image`, `audio`, `resource_link` or `resource` block.
    Part(Part),
    /// A block of a kind this client does not know, by its `type`.
    Other(String),
}

/// One streamed piece of a message. Chunks with the same `message_id` join.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Chunk {
    pub message_id: Option<String>,
    pub content: Content,
}

/// What the agent is doing, from `state_update`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AgentState {
    Running,
    Idle,
    Other,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum ToolStatus {
    #[default]
    Pending,
    InProgress,
    Completed,
    Failed,
}

/// Something a tool call produced.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ToolContent {
    Text(String),
    Diff {
        path: String,
        old_text: Option<String>,
        new_text: String,
    },
    /// A terminal the agent created (`{"type": "terminal", "terminalId"}`): the command's output is
    /// in the call's [`Stream`] (adapters that run the command themselves send it in `_meta`).
    Terminal(String),
    /// A picture, file or sound among the output (`content` blocks that are not text).
    Part(Part),
}

/// A file and line a tool call touches.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Location {
    pub path: String,
    /// 1-based.
    pub line: Option<u32>,
}

/// How a command ended.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Exit {
    /// `None` when the agent could not tell (a signal ended it).
    pub code: Option<i64>,
    pub signal: Option<String>,
}

/// What an update says about a command's output in its `_meta`: codex-acp and pi-acp announce a command
/// with `content: [{type: terminal}]` and send what it prints only here, as pieces to append:
/// `terminal_output_delta` / `terminal_output` `{terminal_id, data}`, `terminal_exit`
/// `{terminal_id, exit_code, signal}`, `terminal_info` `{cwd}` and `mcp_output_delta` `{data}` (the
/// progress lines of an MCP call).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Stream {
    /// What the command printed in this update, to append.
    pub output: String,
    /// Progress lines of an MCP call, to append.
    pub progress: String,
    /// The command ended.
    pub exit: Option<Exit>,
    /// Where the command runs.
    pub cwd: Option<String>,
}

impl Stream {
    /// Whether the update said nothing about a terminal.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.output.is_empty()
            && self.progress.is_empty()
            && self.exit.is_none()
            && self.cwd.is_none()
    }

    fn from_meta(meta: Option<&Value>) -> Stream {
        let mut out = Stream::default();
        let Some(meta) = meta else { return out };
        for key in ["terminal_output_delta", "terminal_output"] {
            if let Some(data) = meta.get(key).and_then(|m| str_of(m, "data")) {
                out.output.push_str(data);
            }
        }
        if let Some(data) = meta.get("mcp_output_delta").and_then(|m| str_of(m, "data")) {
            out.progress.push_str(data);
        }
        if let Some(exit) = meta.get("terminal_exit") {
            out.exit = Some(Exit {
                code: exit.get("exit_code").and_then(Value::as_i64),
                signal: str_of(exit, "signal").map(str::to_string),
            });
        }
        out.cwd = meta
            .get("terminal_info")
            .and_then(|m| str_of(m, "cwd"))
            .map(str::to_string);
        out
    }
}

/// A tool call, or an update to one: every field but the id may be absent in an
/// update, and a client merges what is present into what it has.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ToolCall {
    pub id: String,
    pub title: Option<String>,
    /// The agent's programmatic name for the tool (`Bash`), when it gives one.
    pub name: Option<String>,
    pub kind: Option<String>,
    pub status: Option<ToolStatus>,
    pub raw_input: Option<Value>,
    pub content: Vec<ToolContent>,
    /// The files it touches.
    pub locations: Vec<Location>,
    /// `rawOutput` as text, when it has a text shape (a string, or an object with `output`, `stdout` and
    /// `stderr`, `aggregated_output`, `formatted_output` or `text`).
    pub raw_output: Option<String>,
    /// What `_meta` says about the command's terminal.
    pub stream: Stream,
    /// omp's `task` call: how far each subagent has got (`rawOutput.details.progress[]`), at most
    /// [`SUBAGENTS_MAX`].
    pub progress: Vec<SubagentProgress>,
    /// omp's `task` call: the subagents the launch asked for (`rawInput.tasks[]`), all pending, in order.
    pub launched: Vec<SubagentProgress>,
}

/// The most subagents of one call that are read.
pub const SUBAGENTS_MAX: usize = 16;
/// The most characters of a subagent's assignment, and of a tool line, that are kept.
const ASSIGNMENT_MAX: usize = 300;
const TOOL_LINE_MAX: usize = 80;
/// How many of a subagent's last tools are kept.
const RECENT_TOOLS: usize = 3;

/// Where one subagent of a `task` call stands (omp's `AgentProgress.status`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum SubagentState {
    /// Asked for, not running yet (or a status this client does not know).
    #[default]
    Pending,
    Running,
    Completed,
    Failed,
    Aborted,
}

impl SubagentState {
    /// Whether it still has work to do.
    #[must_use]
    pub fn is_active(self) -> bool {
        matches!(self, SubagentState::Pending | SubagentState::Running)
    }
}

/// One subagent of an omp `task` call, read from `rawOutput.details.progress[]` (or, before any progress
/// came, from the launch's `rawInput.tasks[]`). Shapes: `AgentProgress` in oh-my-pi, checked against a real
/// capture (`tests/fixtures/acp_task_updates.json`).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct SubagentProgress {
    /// omp's id for it (the name of its log file).
    pub id: String,
    /// What the person reads: the launch's `tasks[].name` when one matches (see [`name_subagents`]), else
    /// `id`.
    pub name: String,
    /// The agent type (`task`, `reviewer`).
    pub agent: String,
    pub state: SubagentState,
    /// What it was asked, on one line, cut at 300 characters.
    pub assignment: String,
    /// Tools it has called.
    pub tool_count: u64,
    pub duration_ms: u64,
    /// The tool it is in now with its subject (`read lib/auth.ts`).
    pub current_tool: Option<String>,
    /// Its last three finished tools, oldest first, each with a short subject.
    pub recent_tools: Vec<String>,
    pub tokens: Option<u64>,
    /// omp's `index` of it, else its place in the list: how the launch's task is found.
    pub index: usize,
}

/// A `session/update` payload.
#[derive(Clone, Debug, PartialEq)]
pub enum SessionUpdate {
    AgentMessage(Chunk),
    UserMessage(Chunk),
    AgentThought(Chunk),
    ToolCall(ToolCall),
    ToolCallUpdate(ToolCall),
    State {
        state: AgentState,
        stop_reason: Option<String>,
    },
    /// `Some(None)` is a title that was cleared.
    SessionInfo {
        title: Option<Option<String>>,
        /// When the session last changed (`updatedAt`, an ISO 8601 time), when the agent says.
        updated_at: Option<String>,
    },
    /// The agent's mode changed (`plan`, `act`, ...).
    Mode(String),
    /// The session's config options changed (the model, the mode, the thinking level).
    Config(Vec<crate::session::vendored::acp::ConfigOption>),
    /// The slash commands the agent offers; each update replaces the whole list.
    Commands(Vec<Command>),
    /// The agent's plan: a checklist it keeps up to date; each update replaces the whole list
    /// (an empty one clears it).
    Plan(Vec<PlanEntry>),
    /// How much of the context window is used, and what the session has cost.
    Usage {
        used: u64,
        size: u64,
        /// `(amount, currency)`, cumulative for the session.
        cost: Option<(f64, String)>,
    },
    /// A live notice for the person (`notice`): not part of the conversation and not replayed. The
    /// agent sends it only to a client that said `session.notices` in `initialize`.
    Notice {
        /// `info`, `warning`, `error`, or an agent's own (`_...`).
        severity: String,
        title: String,
        description: Option<String>,
    },
    /// The agent is compacting its context (`compaction_update`; only to a client that said
    /// `session.compaction`).
    Compaction {
        id: String,
        /// `running`, `completed`, `failed`, or one this client does not know.
        status: String,
        error: Option<String>,
    },
    /// Plans, command lists and anything newer, by `sessionUpdate`.
    Other(String),
}

impl SessionUpdate {
    /// Reads the `update` member of a `session/update` notification. `None`
    /// when it names no kind at all.
    #[must_use]
    pub fn from_value(u: &Value) -> Option<SessionUpdate> {
        let kind = u.get("sessionUpdate")?.as_str()?;
        Some(match kind {
            "agent_message_chunk" => SessionUpdate::AgentMessage(chunk(u)?),
            "user_message_chunk" => SessionUpdate::UserMessage(chunk(u)?),
            "agent_thought_chunk" => SessionUpdate::AgentThought(chunk(u)?),
            "tool_call" => SessionUpdate::ToolCall(ToolCall::from_value(u)?),
            "tool_call_update" => SessionUpdate::ToolCallUpdate(ToolCall::from_value(u)?),
            "state_update" => SessionUpdate::State {
                state: match str_of(u, "state") {
                    Some("running") => AgentState::Running,
                    Some("idle") => AgentState::Idle,
                    _ => AgentState::Other,
                },
                stop_reason: str_of(u, "stopReason").map(str::to_string),
            },
            "session_info_update" => SessionUpdate::SessionInfo {
                title: u.get("title").map(|t| {
                    t.as_str()
                        .filter(|s| !s.trim().is_empty())
                        .map(str::to_string)
                }),
                updated_at: str_of(u, "updatedAt").map(str::to_string),
            },
            "current_mode_update" => {
                match str_of(u, "currentModeId").or_else(|| str_of(u, "modeId")) {
                    Some(id) => SessionUpdate::Mode(id.to_string()),
                    None => SessionUpdate::Other(kind.to_string()),
                }
            }
            "config_option_update" => SessionUpdate::Config(crate::session::vendored::acp::parse_config_options(
                u.get("configOptions").unwrap_or(&Value::Null),
            )),
            "plan" => SessionUpdate::Plan(plan_entries(u.get("entries"))),
            "plan_update" => match u.get("plan") {
                Some(p) if str_of(p, "type") == Some("items") => {
                    SessionUpdate::Plan(plan_entries(p.get("entries")))
                }
                _ => SessionUpdate::Other(kind.to_string()),
            },
            "available_commands_update" => SessionUpdate::Commands(
                u.get("availableCommands")
                    .and_then(Value::as_array)
                    .into_iter()
                    .flatten()
                    .filter_map(Command::from_value)
                    .collect(),
            ),
            "usage_update" => match (
                u.get("used").and_then(Value::as_u64),
                u.get("size").and_then(Value::as_u64),
            ) {
                (Some(used), Some(size)) if size > 0 => SessionUpdate::Usage {
                    used,
                    size,
                    cost: u.get("cost").and_then(|c| {
                        Some((c.get("amount")?.as_f64()?, str_of(c, "currency")?.to_string()))
                    }),
                },
                _ => SessionUpdate::Other(kind.to_string()),
            },
            "notice" => match str_of(u, "title").map(clean_line).filter(|t| !t.is_empty()) {
                Some(title) => SessionUpdate::Notice {
                    severity: str_of(u, "severity").unwrap_or("info").to_string(),
                    title,
                    description: str_of(u, "description")
                        .map(clean_text)
                        .filter(|d| !d.is_empty()),
                },
                None => SessionUpdate::Other(kind.to_string()),
            },
            "compaction_update" => match str_of(u, "compactionId") {
                Some(id) => SessionUpdate::Compaction {
                    id: id.to_string(),
                    status: str_of(u, "status").unwrap_or("running").to_string(),
                    error: str_of(u, "error").map(clean_line).filter(|e| !e.is_empty()),
                },
                None => SessionUpdate::Other(kind.to_string()),
            },
            other => SessionUpdate::Other(other.to_string()),
        })
    }
}

/// Where one step of the agent's plan stands.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PlanStatus {
    Pending,
    InProgress,
    Completed,
}

/// One step of the agent's plan.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PlanEntry {
    pub content: String,
    pub status: PlanStatus,
}

/// The steps in a plan's `entries`: control characters removed (the text goes to a terminal),
/// steps with no text skipped.
fn plan_entries(v: Option<&Value>) -> Vec<PlanEntry> {
    v.and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|e| {
            let content: String = str_of(e, "content")?
                .chars()
                .map(|c| if c == '\n' || c == '\t' { ' ' } else { c })
                .filter(|c| !is_unsafe_control(*c))
                .collect();
            let content = content.trim().to_string();
            (!content.is_empty()).then(|| PlanEntry {
                content,
                status: match str_of(e, "status") {
                    Some("completed") => PlanStatus::Completed,
                    Some("in_progress") => PlanStatus::InProgress,
                    _ => PlanStatus::Pending,
                },
            })
        })
        .collect()
}

/// A slash command from `available_commands_update`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Command {
    /// Without the leading slash; may contain `:` (`skill:review`).
    pub name: String,
    pub description: String,
    /// What the argument looks like (`input.hint`), when the command takes one.
    pub hint: Option<String>,
}

impl Command {
    /// `None` for an entry with no usable name. The text goes to a terminal, so control
    /// characters are removed from every field.
    fn from_value(v: &Value) -> Option<Command> {
        let safe = |s: &str| -> String { s.chars().filter(|c| !is_unsafe_control(*c)).collect() };
        let name = safe(str_of(v, "name")?.trim_start_matches('/'))
            .trim()
            .to_string();
        // A name is one word: one with a space in it could never be typed or run.
        if name.is_empty() || name.chars().any(char::is_whitespace) {
            return None;
        }
        Some(Command {
            name,
            description: safe(str_of(v, "description").unwrap_or(""))
                .trim()
                .to_string(),
            hint: v
                .get("input")
                .and_then(|i| str_of(i, "hint"))
                .map(|h| safe(h).trim().to_string())
                .filter(|h| !h.is_empty()),
        })
    }
}

fn str_of<'v>(v: &'v Value, key: &str) -> Option<&'v str> {
    v.get(key)?.as_str()
}

/// One line of an agent's text: control characters out, white space folded.
fn clean_line(s: &str) -> String {
    s.chars()
        .map(|c| if c.is_whitespace() { ' ' } else { c })
        .filter(|c| !is_unsafe_control(*c))
        .collect::<String>()
        .trim()
        .to_string()
}

/// Text of an agent's, control characters out; newlines and tabs stay.
fn clean_text(s: &str) -> String {
    s.chars()
        .filter(|c| !is_unsafe_control(*c))
        .collect::<String>()
        .trim()
        .to_string()
}

/// The last word of a path or address, for what a person reads.
fn base_name(uri: &str) -> &str {
    uri.trim_end_matches('/').rsplit('/').next().unwrap_or(uri)
}

/// Bytes a base64 text of this length decodes to (an estimate good to two bytes).
fn decoded_len(base64: &str) -> u64 {
    let pad = base64.bytes().rev().take_while(|b| *b == b'=').count();
    (base64.len() as u64 / 4 * 3).saturating_sub(pad as u64)
}

/// An `image`, `audio`, `resource_link` or `resource` block; `None` for any other type.
fn part_of(c: &Value) -> Option<Part> {
    let named = |name: Option<&str>, uri: Option<&str>, fallback: &str| -> String {
        name.map(clean_line)
            .filter(|n| !n.is_empty())
            .or_else(|| uri.map(|u| clean_line(base_name(u))).filter(|n| !n.is_empty()))
            .unwrap_or_else(|| fallback.to_string())
    };
    match str_of(c, "type")? {
        "image" => {
            let data = str_of(c, "data");
            Some(Part {
                kind: PartKind::Image,
                name: named(None, str_of(c, "uri"), "image"),
                uri: str_of(c, "uri").map(str::to_string),
                mime: str_of(c, "mimeType").map(str::to_string),
                size: data.map(decoded_len),
                data: data
                    .filter(|d| d.len() <= PART_DATA_MAX)
                    .map(str::to_string),
            })
        }
        "audio" => Some(Part {
            kind: PartKind::Audio,
            name: "audio".to_string(),
            uri: None,
            mime: str_of(c, "mimeType").map(str::to_string),
            size: str_of(c, "data").map(decoded_len),
            data: None,
        }),
        "resource_link" => {
            let uri = str_of(c, "uri");
            if str_of(c, "name").is_none() && uri.is_none() {
                return None;
            }
            Some(Part {
                kind: PartKind::Link,
                name: named(str_of(c, "name"), uri, "file"),
                uri: uri.map(str::to_string),
                mime: str_of(c, "mimeType").map(str::to_string),
                size: c.get("size").and_then(Value::as_u64),
                data: None,
            })
        }
        "resource" => {
            let r = c.get("resource")?;
            let uri = str_of(r, "uri");
            Some(Part {
                kind: PartKind::Resource,
                name: named(None, uri, "resource"),
                uri: uri.map(str::to_string),
                mime: str_of(r, "mimeType").map(str::to_string),
                size: str_of(r, "text")
                    .map(|t| t.len() as u64)
                    .or_else(|| str_of(r, "blob").map(decoded_len)),
                data: None,
            })
        }
        _ => None,
    }
}

fn chunk(u: &Value) -> Option<Chunk> {
    let c = u.get("content")?;
    let kind = str_of(c, "type")?;
    let content = if kind == "text" {
        Content::Text(str_of(c, "text").unwrap_or("").to_string())
    } else if let Some(part) = part_of(c) {
        Content::Part(part)
    } else {
        Content::Other(kind.to_string())
    };
    Some(Chunk {
        message_id: str_of(u, "messageId").map(str::to_string),
        content,
    })
}

/// The text a tool's `rawOutput` holds, for the shapes agents use: a string, or an object with the
/// output under one of a few names (`stdout` and `stderr` are joined).
fn raw_output_text(v: &Value) -> Option<String> {
    let text = match v {
        Value::String(s) => s.clone(),
        Value::Object(o) => {
            let field = |k: &str| o.get(k).and_then(Value::as_str).filter(|s| !s.is_empty());
            if let Some(s) = ["output", "aggregated_output", "formatted_output", "text"]
                .iter()
                .find_map(|k| field(k))
            {
                s.to_string()
            } else {
                match (field("stdout"), field("stderr")) {
                    (Some(a), Some(b)) => format!("{a}\n{b}"),
                    (Some(s), None) | (None, Some(s)) => s.to_string(),
                    (None, None) => return None,
                }
            }
        }
        _ => return None,
    };
    (!text.is_empty()).then_some(text)
}

/// `text` cut to `max` characters, with an ellipsis when it was cut.
fn cut_chars(text: &str, max: usize) -> String {
    if text.chars().count() <= max {
        return text.to_string();
    }
    let mut out: String = text.chars().take(max.saturating_sub(1)).collect();
    out.truncate(out.trim_end().len());
    out.push('…');
    out
}

/// A tool's name and, when there is one, its subject, on one short line: `read lib/auth.ts`.
fn tool_line(tool: &str, subject: Option<&str>) -> Option<String> {
    let tool = clean_line(tool);
    if tool.is_empty() {
        return None;
    }
    let subject = subject.map(clean_line).filter(|s| !s.is_empty());
    let line = match subject {
        Some(s) => format!("{tool} {s}"),
        None => tool,
    };
    Some(cut_chars(&line, TOOL_LINE_MAX))
}

/// `rawOutput.details.progress[]` of an omp `task` call: one entry per subagent, at most
/// [`SUBAGENTS_MAX`]. An entry without a usable shape is skipped; anything else is empty.
fn subagent_progress(raw_output: &Value) -> Vec<SubagentProgress> {
    let Some(list) = raw_output
        .get("details")
        .and_then(|d| d.get("progress"))
        .and_then(Value::as_array)
    else {
        return Vec::new();
    };
    list.iter()
        .take(SUBAGENTS_MAX)
        .enumerate()
        .filter(|(_, p)| p.is_object())
        .map(|(at, p)| {
            let text = |k: &str| str_of(p, k).map(clean_line).unwrap_or_default();
            let id = text("id");
            let assignment = Some(text("assignment"))
                .filter(|a| !a.is_empty())
                .unwrap_or_else(|| text("task"));
            let recent: Vec<String> = p
                .get("recentTools")
                .and_then(Value::as_array)
                .map(|a| {
                    a.iter()
                        .filter_map(|t| match t {
                            Value::String(name) => tool_line(name, None),
                            _ => tool_line(str_of(t, "tool")?, str_of(t, "args")),
                        })
                        .collect()
                })
                .unwrap_or_default();
            SubagentProgress {
                name: id.clone(),
                id,
                agent: text("agent"),
                state: match str_of(p, "status") {
                    Some("running") => SubagentState::Running,
                    Some("completed") => SubagentState::Completed,
                    Some("failed") => SubagentState::Failed,
                    Some("aborted") => SubagentState::Aborted,
                    _ => SubagentState::Pending,
                },
                assignment: cut_chars(&assignment, ASSIGNMENT_MAX),
                tool_count: p.get("toolCount").and_then(Value::as_u64).unwrap_or(0),
                duration_ms: p.get("durationMs").and_then(Value::as_u64).unwrap_or(0),
                current_tool: str_of(p, "currentTool")
                    .and_then(|t| tool_line(t, str_of(p, "currentToolArgs"))),
                recent_tools: recent[recent.len().saturating_sub(RECENT_TOOLS)..].to_vec(),
                tokens: p.get("tokens").and_then(Value::as_u64),
                index: p
                    .get("index")
                    .and_then(Value::as_u64)
                    .and_then(|n| usize::try_from(n).ok())
                    .unwrap_or(at),
            }
        })
        .collect()
}

/// `rawInput.tasks[]` of an omp `task` launch, as pending subagents. Only items with a `task` string count
/// (omp's shape), so another tool's `tasks` list is not mistaken for one.
fn subagents_launched(raw_input: &Value) -> Vec<SubagentProgress> {
    let Some(list) = raw_input.get("tasks").and_then(Value::as_array) else {
        return Vec::new();
    };
    let items: Vec<(usize, &Value)> = list.iter().take(SUBAGENTS_MAX).enumerate().collect();
    if !items.iter().any(|(_, t)| str_of(t, "task").is_some()) {
        return Vec::new();
    }
    items
        .into_iter()
        .map(|(at, t)| {
            let text = |k: &str| str_of(t, k).map(clean_line).unwrap_or_default();
            let name = text("name");
            SubagentProgress {
                id: name.clone(),
                name,
                agent: text("agent"),
                assignment: cut_chars(&text("task"), ASSIGNMENT_MAX),
                index: at,
                ..SubagentProgress::default()
            }
        })
        .collect()
}

/// Names `progress` from the launch: an entry takes the name of the launch task whose name is its `id`, else
/// of the one at its `index` (its place in the list when omp sends none); with no such task, or an unnamed
/// one, it keeps its `id`. An empty assignment or agent is filled from the same task. omp's ids can carry
/// more than the name the model gave (the log file's name), the launch's name is the one the person read.
pub fn name_subagents(progress: &mut [SubagentProgress], launched: &[SubagentProgress]) {
    for p in progress {
        let task = launched
            .iter()
            .find(|l| !l.name.is_empty() && l.name == p.id)
            .or_else(|| launched.iter().find(|l| l.index == p.index));
        let Some(task) = task else { continue };
        if !task.name.is_empty() {
            p.name.clone_from(&task.name);
        }
        if p.assignment.is_empty() {
            p.assignment.clone_from(&task.assignment);
        }
        if p.agent.is_empty() {
            p.agent.clone_from(&task.agent);
        }
    }
}

impl ToolCall {
    /// Reads a `tool_call` / `tool_call_update` (or a permission request's
    /// `toolCall`). `None` when it has no `toolCallId`.
    #[must_use]
    pub fn from_value(v: &Value) -> Option<ToolCall> {
        Some(ToolCall {
            id: str_of(v, "toolCallId")?.to_string(),
            title: str_of(v, "title")
                .filter(|t| !t.is_empty())
                .map(str::to_string),
            name: str_of(v, "name")
                .map(clean_line)
                .filter(|n| !n.is_empty()),
            kind: str_of(v, "kind").map(str::to_string),
            status: str_of(v, "status").map(|s| match s {
                "completed" => ToolStatus::Completed,
                "failed" => ToolStatus::Failed,
                "in_progress" => ToolStatus::InProgress,
                _ => ToolStatus::Pending,
            }),
            raw_input: v.get("rawInput").cloned(),
            content: v
                .get("content")
                .and_then(Value::as_array)
                .map(|a| a.iter().filter_map(tool_content).collect())
                .unwrap_or_default(),
            locations: v
                .get("locations")
                .and_then(Value::as_array)
                .map(|a| {
                    a.iter()
                        .filter_map(|l| {
                            Some(Location {
                                path: clean_line(str_of(l, "path")?),
                                line: l
                                    .get("line")
                                    .and_then(Value::as_u64)
                                    .and_then(|n| u32::try_from(n).ok()),
                            })
                        })
                        .collect()
                })
                .unwrap_or_default(),
            raw_output: v.get("rawOutput").and_then(raw_output_text),
            stream: Stream::from_meta(v.get("_meta")),
            progress: v.get("rawOutput").map(subagent_progress).unwrap_or_default(),
            launched: v.get("rawInput").map(subagents_launched).unwrap_or_default(),
        })
    }

    /// What the call will run or touch, whole, as the agent sent it: its
    /// command (a string, or argv words), else its path. `None` when it names
    /// neither. Control characters are removed; newlines and tabs stay.
    ///
    /// Codex wraps a shell command as `[bash, -lc, script]`: the script is the
    /// command. Any other argv is shown shell-quoted, so what the person reads
    /// is what would be typed.
    #[must_use]
    pub fn subject(&self) -> Option<String> {
        let raw = self.raw_input.as_ref()?.as_object()?;
        let command = ["command", "cmd"]
            .iter()
            .find_map(|k| command_text(raw.get(*k)?));
        let text = command.or_else(|| {
            ["file_path", "path"]
                .iter()
                .find_map(|k| raw.get(*k)?.as_str().map(str::to_string))
        })?;
        let clean: String = text
            .replace('\t', "    ")
            .chars()
            .filter(|c| !is_unsafe_control(*c))
            .collect();
        let clean = clean.trim_matches('\n').to_string();
        (!clean.is_empty()).then_some(clean)
    }
}

fn tool_content(v: &Value) -> Option<ToolContent> {
    match str_of(v, "type")? {
        "diff" => Some(ToolContent::Diff {
            path: str_of(v, "path")?.to_string(),
            old_text: str_of(v, "oldText").map(str::to_string),
            new_text: str_of(v, "newText").unwrap_or("").to_string(),
        }),
        "content" => {
            let inner = v.get("content")?;
            if str_of(inner, "type") == Some("text") {
                Some(ToolContent::Text(str_of(inner, "text").unwrap_or("").to_string()))
            } else {
                part_of(inner).map(ToolContent::Part)
            }
        }
        "terminal" => str_of(v, "terminalId").map(|id| ToolContent::Terminal(id.to_string())),
        _ => None,
    }
}

fn command_text(v: &Value) -> Option<String> {
    match v {
        Value::String(s) if !s.trim().is_empty() => Some(s.clone()),
        Value::Array(words) if !words.is_empty() => {
            let words: Vec<&str> = words.iter().map(Value::as_str).collect::<Option<_>>()?;
            if words.len() == 3 && matches!(words[1], "-c" | "-lc") {
                Some(words[2].to_string())
            } else {
                Some(
                    words
                        .iter()
                        .map(|w| shell_quote(w))
                        .collect::<Vec<_>>()
                        .join(" "),
                )
            }
        }
        _ => None,
    }
}

/// POSIX single-quoting, only where a word needs it.
fn shell_quote(word: &str) -> String {
    let safe = !word.is_empty()
        && word
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || "_@%+=:,./-".contains(c));
    if safe {
        word.to_string()
    } else {
        format!("'{}'", word.replace('\'', r#"'"'"'"#))
    }
}

/// What a terminal must not be sent from an agent's text: control characters
/// (an escape sequence could rewrite the screen). Newlines and tabs stay.
#[must_use]
pub fn is_unsafe_control(c: char) -> bool {
    // The C0 and C1 controls (an escape sequence could rewrite the screen), and the bidirectional
    // overrides and marks, which can make a command on a permission card read differently from what it is.
    matches!(c, '\u{0}'..='\u{8}' | '\u{b}'..='\u{1f}' | '\u{7f}'..='\u{9f}' | '\u{200e}' | '\u{200f}' | '\u{202a}'..='\u{202e}' | '\u{2066}'..='\u{2069}' | '\u{61c}')
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn tool(raw: Value) -> ToolCall {
        ToolCall {
            id: "t".into(),
            raw_input: Some(raw),
            ..ToolCall::default()
        }
    }

    #[test]
    fn the_command_list_is_read_whole_with_hints_and_without_unusable_entries() {
        let u = json!({"sessionUpdate": "available_commands_update", "availableCommands": [
            {"name": "/compact", "description": "Compact", "input": {"hint": "[focus]"}},
            {"name": ""},
            {"name": "skill:review"},
            {"name": "two words"},
            {"name": "bad\u{1b}[2Jname", "description": "x\u{7}y"}]});
        let Some(SessionUpdate::Commands(c)) = SessionUpdate::from_value(&u) else {
            panic!("commands");
        };
        assert_eq!(c.len(), 3);
        assert_eq!(
            (c[0].name.as_str(), c[0].hint.as_deref()),
            ("compact", Some("[focus]"))
        );
        assert_eq!(
            (
                c[1].name.as_str(),
                c[1].description.as_str(),
                c[1].hint.as_deref()
            ),
            ("skill:review", "", None)
        );
        assert_eq!(
            (c[2].name.as_str(), c[2].description.as_str()),
            ("bad[2Jname", "xy")
        );
        let none = json!({"sessionUpdate": "available_commands_update"});
        assert_eq!(
            SessionUpdate::from_value(&none),
            Some(SessionUpdate::Commands(vec![]))
        );
    }

    #[test]
    fn the_plan_is_a_checklist_replaced_whole_and_an_empty_one_clears_it() {
        let u = json!({"sessionUpdate": "plan", "entries": [
            {"content": "Read the code", "priority": "medium", "status": "completed"},
            {"content": "Fix\nthe \u{1b}bug", "status": "in_progress"},
            {"content": "  "},
            {"content": "Run tests", "status": "whatever"}]});
        let Some(SessionUpdate::Plan(p)) = SessionUpdate::from_value(&u) else {
            panic!("a plan")
        };
        assert_eq!(
            p.iter()
                .map(|e| (e.content.as_str(), e.status))
                .collect::<Vec<_>>(),
            [
                ("Read the code", PlanStatus::Completed),
                ("Fix the bug", PlanStatus::InProgress),
                ("Run tests", PlanStatus::Pending)
            ]
        );
        let nested = json!({"sessionUpdate": "plan_update", "plan": {"type": "items", "entries": [{"content": "a", "status": "pending"}]}});
        assert!(
            matches!(SessionUpdate::from_value(&nested), Some(SessionUpdate::Plan(p)) if p.len() == 1)
        );
        let other = json!({"sessionUpdate": "plan_update", "plan": {"type": "text"}});
        assert!(matches!(
            SessionUpdate::from_value(&other),
            Some(SessionUpdate::Other(_))
        ));
        let cleared = json!({"sessionUpdate": "plan", "entries": []});
        assert_eq!(
            SessionUpdate::from_value(&cleared),
            Some(SessionUpdate::Plan(vec![]))
        );
    }

    #[test]
    fn an_attached_file_in_a_message_reads_as_a_link_named_by_its_path() {
        let u = json!({"sessionUpdate":"user_message_chunk","content":{"type":"resource_link","uri":"file:///w/a.rs","name":"src/a\u{1b}.rs"}});
        assert_eq!(
            SessionUpdate::from_value(&u),
            Some(SessionUpdate::UserMessage(Chunk {
                message_id: None,
                content: Content::Part(Part {
                    kind: PartKind::Link,
                    name: "src/a.rs".into(),
                    uri: Some("file:///w/a.rs".into()),
                    mime: None,
                    size: None,
                    data: None
                })
            }))
        );
        // Without a name the file is named by its address.
        let nameless = json!({"sessionUpdate":"user_message_chunk","content":{"type":"resource_link","uri":"file:///w/a.rs"}});
        assert!(matches!(
            &SessionUpdate::from_value(&nameless),
            Some(SessionUpdate::UserMessage(Chunk {
                content: Content::Part(Part { name, .. }),
                ..
            })) if name == "a.rs"
        ));
        // A link with neither is nothing a person could read.
        let empty = json!({"sessionUpdate":"user_message_chunk","content":{"type":"resource_link"}});
        assert!(matches!(
            SessionUpdate::from_value(&empty),
            Some(SessionUpdate::UserMessage(Chunk {
                content: Content::Other(_),
                ..
            }))
        ));
    }

    #[test]
    fn chunks_carry_their_message_id_and_kind_of_content() {
        let u = json!({"sessionUpdate":"agent_message_chunk","messageId":"m1","content":{"type":"text","text":"hi"}});
        assert_eq!(
            SessionUpdate::from_value(&u),
            Some(SessionUpdate::AgentMessage(Chunk {
                message_id: Some("m1".into()),
                content: Content::Text("hi".into())
            }))
        );
        // A picture is a part with its bytes when small, and only counted when big.
        let img = json!({"sessionUpdate":"user_message_chunk","content":{"type":"image","mimeType":"image/png","data":"QUJD"}});
        assert!(matches!(
            SessionUpdate::from_value(&img),
            Some(SessionUpdate::UserMessage(Chunk {
                content: Content::Part(Part { kind: PartKind::Image, size: Some(3), data: Some(_), .. }),
                ..
            }))
        ));
        let big = json!({"sessionUpdate":"user_message_chunk","content":{"type":"image","mimeType":"image/png","data":"A".repeat(PART_DATA_MAX + 4)}});
        assert!(matches!(
            SessionUpdate::from_value(&big),
            Some(SessionUpdate::UserMessage(Chunk {
                content: Content::Part(Part { kind: PartKind::Image, size: Some(n), data: None, .. }),
                ..
            })) if n > PART_DATA_MAX as u64 / 2
        ));
        // A block of a kind nobody knows is kept by its type.
        let odd = json!({"sessionUpdate":"user_message_chunk","content":{"type":"hologram"}});
        assert!(matches!(
            &SessionUpdate::from_value(&odd),
            Some(SessionUpdate::UserMessage(Chunk {
                content: Content::Other(k),
                ..
            })) if k == "hologram"
        ));
    }

    #[test]
    fn the_mode_and_the_context_use_are_read() {
        let m = json!({"sessionUpdate": "current_mode_update", "currentModeId": "plan"});
        assert_eq!(
            SessionUpdate::from_value(&m),
            Some(SessionUpdate::Mode("plan".into()))
        );
        let u = json!({"sessionUpdate": "usage_update", "used": 47, "size": 100});
        assert_eq!(
            SessionUpdate::from_value(&u),
            Some(SessionUpdate::Usage {
                used: 47,
                size: 100,
                cost: None
            })
        );
        // A cost is `(amount, currency)`, and a credit count is a currency too.
        let c = json!({"sessionUpdate": "usage_update", "used": 1, "size": 2,
            "cost": {"amount": 1.25, "currency": "credits"}});
        assert!(matches!(
            &SessionUpdate::from_value(&c),
            Some(SessionUpdate::Usage { cost: Some((a, cur)), .. }) if *a == 1.25 && cur == "credits"
        ));
        // A window of size 0 says nothing: never a division by zero downstream.
        let z = json!({"sessionUpdate": "usage_update", "used": 1, "size": 0});
        assert_eq!(
            SessionUpdate::from_value(&z),
            Some(SessionUpdate::Other("usage_update".into()))
        );
    }

    #[test]
    fn an_unknown_kind_is_kept_and_a_missing_kind_is_none() {
        assert_eq!(
            SessionUpdate::from_value(&json!({"sessionUpdate":"something_newer"})),
            Some(SessionUpdate::Other("something_newer".into()))
        );
        assert_eq!(SessionUpdate::from_value(&json!({"foo":1})), None);
    }

    #[test]
    fn a_tool_update_may_carry_only_what_changed() {
        let u = json!({"sessionUpdate":"tool_call_update","toolCallId":"7","status":"completed"});
        let Some(SessionUpdate::ToolCallUpdate(t)) = SessionUpdate::from_value(&u) else {
            panic!("not a tool update")
        };
        assert_eq!(
            (t.id.as_str(), t.status, t.title),
            ("7", Some(ToolStatus::Completed), None)
        );
    }

    #[test]
    fn diffs_and_text_are_read_from_tool_content() {
        let u = json!({"toolCallId":"1","content":[
            {"type":"diff","path":"a.rs","oldText":"x","newText":"y"},
            {"type":"content","content":{"type":"text","text":"ok"}},
            {"type":"terminal","terminalId":"z"}]});
        let t = ToolCall::from_value(&u).expect("has an id");
        // Text, a diff and a terminal are all kept.
        assert_eq!(t.content.len(), 3);
        assert!(matches!(&t.content[2], ToolContent::Terminal(id) if id == "z"));
    }

    #[test]
    fn the_subject_is_the_command_whole_or_else_the_path() {
        assert_eq!(
            tool(json!({"command":"ls -la"})).subject().as_deref(),
            Some("ls -la")
        );
        assert_eq!(
            tool(json!({"cmd":["bash","-lc","cd x && make"]}))
                .subject()
                .as_deref(),
            Some("cd x && make")
        );
        assert_eq!(
            tool(json!({"command":["git","commit","-m","a b"]}))
                .subject()
                .as_deref(),
            Some("git commit -m 'a b'")
        );
        assert_eq!(
            tool(json!({"file_path":"/etc/hosts"})).subject().as_deref(),
            Some("/etc/hosts")
        );
        assert_eq!(tool(json!({"command":"  "})).subject(), None);
        assert_eq!(tool(json!({"other":1})).subject(), None);
    }

    #[test]
    fn the_subject_cannot_carry_an_escape_sequence() {
        let s = tool(json!({"command":"echo \u{1b}[2J hi\tthere"})).subject();
        assert_eq!(s.as_deref(), Some("echo [2J hi    there"));
    }

    #[test]
    fn a_command_cannot_be_disguised_with_bidirectional_overrides() {
        // U+202E reverses what follows: `rm -rf ~` could be made to read as something harmless.
        let s = tool(json!({"command": "echo \u{202e}txt.elif\u{202c} ; rm -rf ~"}))
            .subject()
            .expect("a subject");
        assert!(!s.chars().any(is_unsafe_control), "{s:?}");
        assert!(
            s.contains("rm -rf ~"),
            "the command itself is untouched: {s:?}"
        );
    }

    #[test]
    fn a_quote_inside_a_word_is_escaped() {
        assert_eq!(shell_quote("it's"), r#"'it'"'"'s'"#);
        assert_eq!(shell_quote(""), "''");
    }
}
